import math
def is_fibonacci_number(n):
    def is_perfect_square(x):
        s = math.isqrt(x)
        return s * s == x
    return is_perfect_square(5 * n * n + 4) or is_perfect_square(5 * n * n - 4)

def fibonacci_index(n):
    if n == 0:
        return 0
    a, b = 0, 1
    idx = 1
    while b < n:
        a, b = b, a + b
        idx += 1
    return idx if b == n else -1

def custom_fibonacci(a, b, n):
    if n == 0:
        return a
    if n == 1:
        return b
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def nth_lucas_number(n):
    a, b = 2, 1
    for _ in range(n):
        a, b = b, a + b
    return a

