def nth_catalan_number(n):
    return math.comb(2 * n, n) // (n + 1)

import math
def binomial_coefficient(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def count_divisors_of_factorial(n):
    if n <= 1:
        return 1
    limit = n
    is_comp = [False] * (limit + 1)
    primes = []
    for p in range(2, limit + 1):
        if not is_comp[p]:
            primes.append(p)
            for m in range(p * p, limit + 1, p):
                is_comp[m] = True
    result = 1
    for p in primes:
        exp = 0
        pw = p
        while pw <= n:
            exp += n // pw
            pw *= p
        result *= (exp + 1)
    return result

import math
def lcm_of_digits(n):
    digits = [int(d) for d in str(n) if d != '0']
    if not digits:
        return 0
    result = 1
    for d in digits:
        result = result * d // math.gcd(result, d)
    return result

def smallest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    for i in range(d - 1, 0, -1):
        take = min(9, remaining)
        if remaining - take < 1:
            take = remaining - 1
        digits[i] = take
        remaining -= take
    digits[0] = remaining
    return int(''.join(map(str, digits)))

def largest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    for i in range(d):
        take = min(9, remaining)
        digits[i] = take
        remaining -= take
    return int(''.join(map(str, digits)))

def is_repunit(n):
    s = str(n)
    return all(c == '1' for c in s)

def most_frequent_digit(n):
    from collections import Counter
    s = str(n)
    counts = Counter(s)
    best = None
    best_count = -1
    for d in '0123456789':
        c = counts.get(d, 0)
        if c > best_count:
            best_count = c
            best = d
    return int(best)

def count_matching_digit_positions(a, b):
    sa, sb = str(a), str(b)
    length = max(len(sa), len(sb))
    sa = sa.zfill(length)
    sb = sb.zfill(length)
    return sum(1 for x, y in zip(sa, sb) if x == y)

def sum_even_fibonacci_below(n):
    a, b = 0, 1
    total = 0
    while a < n:
        if a % 2 == 0:
            total += a
        a, b = b, a + b
    return total

def count_polite_representations(n):
    count_odd_divisors = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 1:
                count_odd_divisors += 1
            j = n // i
            if j != i and j % 2 == 1:
                count_odd_divisors += 1
        i += 1
    return count_odd_divisors - 1

def is_practical_number(n):
    if n == 1:
        return True
    divs = sorted(i for i in range(1, n + 1) if n % i == 0)
    if divs[0] != 1:
        return False
    total = 1
    for d in divs[1:]:
        if d > total + 1:
            return False
        total += d
    return True
